   (30600,'pw30600',1,7,8280,3920,67,3050,2222,67,ARRAY[3248,2153,3339,2228,3439,2178,3334,2101])
 ) AS approved(map_id,map_file,proc_id,map_to,to_x,to_y,to_dir,back_x,back_y,back_dir,poly)
 LOOP
  IF NOT EXISTS (SELECT 1 FROM map_defs WHERE id=r.map_id AND file=r.map_file) THEN
   RAISE EXCEPTION 'Native portal source identity mismatch: % / %',r.map_id,r.map_file;
  END IF;
  SELECT t.* INTO previous FROM map_teleports t
   WHERE t.map_file=r.map_file AND t.proc_id=r.proc_id
    AND t.map_to=r.map_to AND t.to_x=r.to_x AND t.to_y=r.to_y
    AND t.to_dir=r.to_dir AND t.back_x=r.back_x AND t.back_y=r.back_y
    AND t.back_dir=r.back_dir AND t.script=''
   FOR UPDATE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Native portal route identity mismatch: % / %',r.map_file,r.proc_id;
  END IF;
  IF previous.poly IS NOT NULL AND previous.poly IS DISTINCT FROM r.poly THEN
   RAISE EXCEPTION 'Native portal geometry conflict: % / %',r.map_file,r.proc_id;
  END IF;
  UPDATE map_teleports t SET poly=r.poly,transition_owner='client'
   WHERE t.map_file=r.map_file AND t.proc_id=r.proc_id AND t.poly IS NULL;
  GET DIAGNOSTICS affected = ROW_COUNT;
  changed := changed + affected;
  SELECT t.* INTO after_row FROM map_teleports t
   WHERE t.map_file=r.map_file AND t.proc_id=r.proc_id;
  IF after_row.poly IS DISTINCT FROM r.poly
   OR (to_jsonb(after_row)-'poly'-'transition_owner') IS DISTINCT FROM
      (to_jsonb(previous)-'poly'-'transition_owner')
   OR (previous.poly IS NOT NULL AND after_row.transition_owner IS DISTINCT FROM previous.transition_owner)
   OR (previous.poly IS NULL AND after_row.transition_owner <> 'client') THEN
   RAISE EXCEPTION 'Native portal repair postcondition failed: % / %',r.map_file,r.proc_id;
  END IF;
  checked := checked + 1;
 END LOOP;
 IF checked <> 67 THEN
  RAISE EXCEPTION 'Native portal manifest count mismatch: %',checked;
 END IF;
 RAISE NOTICE 'Verified % native portal routes; restored % NULL polygons',checked,changed;
END
$native_portal_geometry$;
